const API_BASE = process.env.REACT_APP_API_BASE || "http://localhost:5000";

export async function getLatestTelemetry() {
  const response = await fetch(`${API_BASE}/api/telemetry/latest`);
  if (!response.ok) {
    return null;
  }
  return response.json();
}

export async function getTelemetryHistory(limit = 20) {
  const response = await fetch(`${API_BASE}/api/telemetry/history?limit=${limit}`);
  if (!response.ok) {
    return { items: [] };
  }
  return response.json();
}

export async function getBatteryStatus() {
  const response = await fetch(`${API_BASE}/api/battery/status`);
  if (!response.ok) {
    return { health: "UNKNOWN", latest: null };
  }
  return response.json();
}
